  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (!isFirefoxTarget) {
      if (e.key === "Process" || e.key === "229") return;
    }

    if (showSlashMenu) {
      if (e.key === "ArrowDown" && filteredSlashCommands.length > 0) {
        e.preventDefault();
        setSlashActiveIndex((prev) =>
          prev + 1 >= filteredSlashCommands.length ? 0 : prev + 1,
        );
        return;
      }
      if (e.key === "ArrowUp" && filteredSlashCommands.length > 0) {
        e.preventDefault();
        setSlashActiveIndex((prev) =>
          prev <= 0 ? filteredSlashCommands.length - 1 : prev - 1,
        );
        return;
      }
      if (
        (e.key === "Enter" || (e.key === "Tab" && !e.shiftKey)) &&
        filteredSlashCommands.length > 0
      ) {
        e.preventDefault();
        const command = filteredSlashCommands[slashActiveIndex];
        if (command) {
          handleSlashCommandSelect(command);
        }
        return;
      }
      if (e.key === "Escape") {
        e.preventDefault();
        form.setFieldValue(
          "message",
          form.values.message.replace(/^\s*\//, ""),
        );
        return;
      }
    }

    if (
      showMentions &&
      (e.key === "ArrowDown" ||
        e.key === "ArrowUp" ||
        e.key === "Enter" ||
        e.key === "Escape")
    ) {
      return;
    }

    if (!isConnectionReady) {
      if (e.key === "Enter") {
        e.preventDefault();
      }
      return;
    }

    if (
      handleChatInputKeyDown({
        e,
        sendWhenEnter,
        typing,
        isSending: false,
      })
    ) {
      e.preventDefault();
      stopListening();
      handleComposerSend();
    }
  };

